/* Shop filler + Lincoln catalog lab packets. Generated from Instructor Desk. */
window.SHOP_LABS = [{"source":"filler","id":"lab-shop-tubing","courseCode":"HCR101","title":"Copper coupon — cut, flare, swage, solder, nitrogen-test","durationMin":90,"groupSize":"Pairs","why":"First-years split flares and skip the pressure test. This coupon is the gate before they touch a live unit. Pretty solder with a leaking flare is a fail.","timebox":"Hold at ream and at nitrogen. Do not let the bay race to the torch.","openScript":"Ninety minutes. I set nitrogen. You do not. Split flare is a cut-back, not a grade. Needle holds three minutes or you redo. Torch stays on the brick.","setup":["Night before: 3/8 and 1/4 ACR in 10-in sticks, one pair per bay. Do not ream them — they ream.","Nitrogen: one regulator you own. Shop pressure 120 psig on the whip. Caps on. They do not set the bottle.","Fire brick, torch, extra flare nuts (they will split two). Extinguisher posted. Quench bucket with clean water only.","Print student packet per pair. Print this instructor card once."],"instructorRun":["Open 4 min: no oxygen, hot copper looks cold, you set nitrogen. Point at the extinguisher.","Walk cuts. If the ID is not shiny they do not flare.","Hold the flare in your hand. Even face, no cracks, nut spins. Split = cut back. No ‘effort’ credit.","Watch the first 30 seconds of soap. Any bubble is a repair, not ‘it’s small.’","Last 10 min: stamp initials. Fail coupons go in the redo bin, not the trash."],"holds":[{"step":3,"lookFor":"ID shiny. You initial the packet."},{"step":5,"lookFor":"Flare in your hand. Even, no split."},{"step":9,"lookFor":"Needle holds 3 min at shop pressure."}],"plantFaults":["Drop one cracked flare nut in a bay so they learn to inspect hardware.","If a pair finishes 20 min early: swap coupons and grade each other’s leak test."],"failLooksLike":["Pretty solder, leaking flare — they will argue the solder is the grade. Grade the leak.","Oxygen on the whip — stop the bay. That pair is done.","Quenching in a bucket they dumped flux in."],"passLine":"Square cut, serviceable 45° flare, filled joint, nitrogen holds 3 minutes. All four or they redo.","objectives":["Square, reamed cuts on 3/8 in. and 1/4 in. ACR","A 45° flare that seats without splitting","A swaged, filled solder joint","Nitrogen test with no soap bubbles and a holding needle"],"safety":["Glasses on. Torch only on the fire brick.","Instructor sets nitrogen. Never oxygen.","Hot copper looks like cold copper. Quench, then rack.","Know the extinguisher before the torch lights."],"ppe":["Safety glasses","Gloves for hot work","Closed-toe boots","Shop shirt — no synthetics at the torch"],"tools":["Tubing cutter","Reamer / deburr","Flaring yoke","Swage punch","Torch and solder","Nitrogen regulator and whip (instructor)","Bubble solution","Flare-nut wrenches"],"materials":["3/8 in. and 1/4 in. ACR","Flare nuts","Solder and flux","Sand cloth","Name tag"],"procedure":["Sketch the coupon: 8 in. of 3/8 with a 45° flare, a swage onto 1/4, test fitting on the other end. Instructor initials the sketch.","Cut both tubes. Look down the ID. If you see a burr, you are not done.","Ream and clean until the ID is shiny. Hold for instructor. Do not flare until they initial.","Slide the flare nut on first. Flare the 3/8. Stop when the cone just seats — do not keep cranking.","Hold the flare up. Even white face, no cracks, nut spins free. Fail = cut 1 in. back and redo.","Swage the other end. Insert 1/4 to proper depth. Dry-fit before flux.","Flux, heat, pull solder. Capillary should fill and wipe clean. No blobs, no unfilled ring.","Cap the coupon. Instructor puts nitrogen on the whip. Shop pressure is posted (typically 120 psig).","Soap every joint. Hold 3 minutes. Needle drop or a bubble = repair and retest. That is the proving step.","Stamp initials. Submit. Redo bin if any joint failed."],"dataColumns":["Joint","Visual","Soap (Y/N)","psig start","psig @ 3 min","Instructor"],"dataRows":4,"analysis":[{"id":"a1","type":"short","prompt":"The flare split. Name two causes and the fix. Do not write ‘be more careful.’","answer":"Over-travel on the yoke, dull cone, unreamed ID, or work-hardened copper. Cut back, ream, anneal if the copper is springy, stop when the face is even.","points":4},{"id":"a2","type":"short","prompt":"Nitrogen soap held. Why is that not enough once refrigerant is in a system?","answer":"Soap finds wet joints at high ΔP on a coupon. Field leaks on refrigerant need electronic or ultrasonic search. Fabrication QA ≠ leak search on a charged unit.","points":3}],"competencies":[{"id":"c1","label":"Square cut and ream — instructor saw the ID"},{"id":"c2","label":"Serviceable 45° flare in the instructor’s hand"},{"id":"c3","label":"Filled solder joint"},{"id":"c4","label":"Nitrogen holds 3 minutes, no soap"}]},{"source":"filler","id":"lab-shop-circuits","courseCode":"HCR102","title":"Ohm’s law board, compressor terminals, capacitor µF","durationMin":90,"groupSize":"Pairs","why":"They will guess C-S-R and skip discharging the cap. This lab makes them predict, measure, and name the failed winding before they work live.","timebox":"25 min board, 25 min compressor/cap, 20 min planted fault, 10 min ticket. 90-minute bay.","openScript":"Predict on paper before the meter. Discharge the cap with the resistor — I watch. Name the planted fault before the tape comes off.","setup":["Low-voltage boards with two known resistors or lamps. Tape the values on the back — they calculate first.","Isolated compressors or hermetic trainers, LOTO, windings labeled under a flap you control.","Dual run capacitors, known-good and one that’s 20% low. Resistor discharge leads at every bay.","One planted open and one planted short under electrical tape. You know which bay is which."],"instructorRun":["No 120 V unless you stand there. Boards stay 24 V until the last 20 min.","They write predicted I and V before the meter comes out. No meter until the prediction is on paper.","Watch capacitor discharge. If they grab terminals first, stop the pair.","Planted fault: they get one look at the schematic. Diagnosis is meter-only."],"holds":[{"step":2,"lookFor":"Predictions on paper before they energize."},{"step":6,"lookFor":"You saw the cap discharged."},{"step":8,"lookFor":"They named open vs short before peeling tape."}],"plantFaults":["Open lamp in series. They should see voltage across the open, zero current.","Shorted branch in parallel. Total current high, that branch near 0 Ω.","Start winding open on one compressor (OL on C-S)."],"failLooksLike":["Meter on current while still in parallel across the supply — stop them.","Cap still charged and they’re swapping it.","They call C-S-R without three readings plus ground."],"passLine":"Predictions within 10%, C-S-R identified, cap µF vs nameplate, planted fault named before the tape comes off.","objectives":["Predict then measure series and parallel","Prove I = E/R on paper and on the meter","Identify C, S, R and winding-to-ground","Discharge and test a dual run capacitor"],"safety":["Boards are 24 V until the instructor says otherwise.","One hand in pocket on 120/240. CAT-rated meter.","Discharge capacitors with a resistor. Not a screwdriver across the terminals as a habit.","LOTO any motor you ohm at the terminals."],"ppe":["Safety glasses","Meter with insulated probes","No jewelry on live panels"],"tools":["DMM","Clamp-on if 120 V","Capacitor tester","Screwdrivers","Alligator leads","Discharge resistor"],"materials":["Trainer board","Known resistors or lamps","Dual run capacitor","Isolated compressor"],"procedure":["Write two known load values on the data sheet. Predict series current and each voltage drop. Do not pick up the meter yet.","Instructor checks the prediction. Then build series, energize, measure. Record % error.","Rebuild parallel. Predict branch currents and total. Measure. Error over 10% = re-range the meter and do it again.","LOTO the compressor. Confirm zero volts. Then ohms: C-S, C-R, S-R. The two smaller add to the largest. That largest is S-R. Common is the remaining terminal shared by the two smaller.","Winding to ground / shell. Must be OL. Any continuity to ground is a fail — tag it, don’t run it.","Discharge the dual cap with the resistor. Instructor watches. Then µF on Herm and Fan vs nameplate ±6%.","Write the terminal map and µF on the packet before the planted fault.","Instructor plants an open or short. Diagnose with the meter only. Name the fault out loud. Then you may peel the tape."],"dataColumns":["Circuit","Predicted I","Measured I","Predicted V","Measured V","% error"],"dataRows":4,"analysis":[{"id":"a1","type":"calc","prompt":"Series: two 50 Ω on 24 V. Predicted I and each drop?","answer":"0.24 A; 12 V each","points":4,"work":"Rt = 100 Ω. I = 24/100 = 0.24 A. V = 0.24 × 50 = 12 V."},{"id":"a2","type":"short","prompt":"C-S is OL. C-R and R-S look normal. What failed, and will it start?","answer":"Start winding open (or overload in that path). It will not start. Do not keep hitting the contactor.","points":3}],"competencies":[{"id":"c1","label":"Series: predicted then measured"},{"id":"c2","label":"Parallel: predicted then measured"},{"id":"c3","label":"C-S-R map + ground OL"},{"id":"c4","label":"Cap discharged, µF recorded"},{"id":"c5","label":"Planted fault named before tape off"}]},{"source":"filler","id":"lab-shop-furnace","courseCode":"HCR103","title":"Gas furnace — sequence, manifold, flame rod, combustion, rise","durationMin":90,"groupSize":"Pairs","why":"Techs jumper rollout and chase ‘no heat’ with a new igniter. This lab forces sequence, manifold pressure, µA, CO, and temperature rise before any part.","timebox":"10 walk-down, 25 sequence, 15 manifold + µA, 15 combustion, 20 planted fault. 90-minute bay.","openScript":"No jumper on rollout. I fire the first unit, then you run yours. Ambient CO is a required number. If it climbs, the bay is dead — that is the lesson.","setup":["CO monitor on in the bay. Fresh analyzer filters. You know the shutdown number (leave if ambient CO climbs).","Manometer zeroed. Flame-rod lead ready for series µA. Do not leave a jumper on rollout from yesterday.","Nameplate rise range and manifold pressure posted on the trainer (NG typically 3.5 in. w.c.).","Faults ready: pressure-switch hose off, dirty flame rod, inducer unplugged. One fault per pair, not all three."],"instructorRun":["You fire the first unit. They watch. Then they run theirs.","No jumper on safety switches. If they ask, the answer is no.","Manifold: they may read. They do not turn the regulator without you.","If ambient CO rises, kill the bay. Lab is over. That is the lesson.","Planted fault after they have a clean sequence on paper."],"holds":[{"step":2,"lookFor":"Highlighter path on W through the safeties. You initial."},{"step":4,"lookFor":"Manifold number vs nameplate. You are standing there."},{"step":6,"lookFor":"Ambient CO recorded before they call it done."}],"plantFaults":["Pressure-switch hose off — inducer runs, no igniter.","Dirty flame rod — lights, then drops out.","Unplugged inducer — nothing after W.","Filter blocked — high rise, they must catch airflow before touching gas."],"failLooksLike":["Jumper on rollout or limit.","Combustion numbers with the probe sitting on the floor.","Opening the gas valve because rise is high.","Calling a new board because they skipped µA."],"passLine":"Timed sequence, manifold vs nameplate, flame-rod µA, combustion with ambient CO, rise in range or airflow named. Then a ticket on one planted fault.","objectives":["Meter a complete call-for-heat sequence","Read manifold pressure vs nameplate","Series-measure flame-sensor microamps","Combustion analysis including ambient CO","Temperature rise vs nameplate — airflow before gas"],"safety":["CO monitor on. If ambient CO climbs, shut down and ventilate.","Do not jumper rollout or limit.","Vent and combustion air confirmed before firing.","Instructor present for any gas-train adjustment."],"ppe":["Glasses","Gloves","CO personal monitor if issued"],"tools":["DMM with µA","Manometer (in. w.c.)","Combustion analyzer","Static probes","Schematic highlighter"],"materials":["Running gas furnace trainer","Analyzer paper filters","Flame-sensor cleaning kit"],"procedure":["Walk-down: model, gas type, vent, filter, nameplate rise and manifold. Photograph the rating plate.","Highlight W on the schematic through every safety. Instructor initials the path.","Call for heat. Time and meter each step: inducer, pressure switch, igniter, valve, flame prove, blower. Write seconds, not ‘it ran.’","Manifold pressure. Compare to nameplate (NG often 3.5 in. w.c.). Do not adjust. If it’s off, get the instructor.","Series-measure flame-rod µA. Shop spec is posted (often ≥ 1 µA — use the OEM). Clean and re-measure if low.","Analyzer in the flue at the right depth. Record O2, CO, CO2, stack, efficiency, and ambient CO. Ambient is not optional.","TESP and temperature rise. Rise high = filter, blower, registers — not more gas.","Instructor plants one fault. Diagnose on paper: which step died, which switch, which number proves it.","Write a no-heat ticket with before numbers. No part name until the system (air, gas, ignition, safety) is named."],"dataColumns":["Step","Seconds / reading","Spec","Pass?"],"dataRows":8,"analysis":[{"id":"a1","type":"short","prompt":"Rise is above the nameplate. First three airflow checks. Do not mention the gas valve.","answer":"Filter, blower speed/ECM tap, supply/return static and closed registers. Then coil/heat exchanger restriction. Do not open the manifold to ‘help.’","points":4},{"id":"a2","type":"short","prompt":"Ambient CO is 35 ppm and climbing while the unit fires. Your moves, in order.","answer":"Shut it down. Ventilate. People out. Tell the instructor. Do not keep firing to finish the lab.","points":4}],"competencies":[{"id":"c1","label":"Sequence timed and metered"},{"id":"c2","label":"Manifold vs nameplate"},{"id":"c3","label":"Flame-rod µA"},{"id":"c4","label":"Combustion + ambient CO"},{"id":"c5","label":"Planted-fault ticket with numbers"}]},{"source":"filler","id":"lab-shop-oil","courseCode":"HCR114","title":"Oil burner — electrode geometry, fire, smoke, cad cell","durationMin":90,"groupSize":"Pairs","why":"Repeated reset into a wet firebox is how you get a puff-back. They will reset. You will stop them. Electrode geometry and one clean fire beat a new primary control.","timebox":"LOTO and drawer 20 min. One clean fire 25. Cad cell 15. Ticket 20. 90-minute bay.","openScript":"One reset. Then you lock out and look. A wet firebox is how you get a puff-back. Electrodes to the card, not your eye. I initial the geometry.","setup":["Correct GPH nozzles in a labeled tin. Wrong nozzles in another tin — they must read the stamp.","Electrode gauge on every bay. Primary-control spec card taped to the door (cad-cell ohms in run).","Oil shutoff tagged. Drip pans. No torch in this bay today.","One covered cad cell and one closed oil valve as planted faults — after a clean fire, not before."],"instructorRun":["You pull the first drawer. They watch electrode geometry. Then they set theirs to the card.","One reset. If it doesn’t light, they lock out and look — they do not keep hitting reset.","Air-band changes only with you. Smoke first, then analyzer.","Puff-back talk is not a joke. Wet firebox = you take the bay."],"holds":[{"step":3,"lookFor":"Electrode gap and position match the card. You initial a photo or the packet."},{"step":5,"lookFor":"One clean fire. You saw it."},{"step":6,"lookFor":"Cad-cell ohms in run vs spec. Not guessed."}],"plantFaults":["Cad cell covered — lockout after trial.","Oil valve closed — no fire, they should catch fuel before they blame the primary.","Wrong nozzle GPH in the tin — they must read the stamp."],"failLooksLike":["Third reset into a dark firebox.","Electrodes ‘close enough’ without the gauge.","Blaming the primary with no ohm reading on the cad cell."],"passLine":"Electrodes to card, one clean fire, smoke/CO2 recorded, cad-cell ohms in run, one planted no-heat named without a second reset.","objectives":["Set electrodes to the manufacturer card","Install the correct GPH nozzle and fire once","Read smoke or analyzer","Cad-cell ohms in run vs spec"],"safety":["Contain oil spills. No torch near mist.","One reset. Then LOTO and look. No wet firebox.","Hot breech — gloves.","Know the oil shutoff and the disconnect."],"ppe":["Glasses","Nitrile / oil gloves","Shop coat","Hearing protection as posted"],"tools":["Nozzle wrench","Electrode gauge","Pump pressure gauge","Smoke tester or analyzer","DMM (cad cell)"],"materials":["Correct GPH nozzle","Electrodes","Oil filter element","Rags and drip pan"],"procedure":["Shut down. LOTO. Tag the oil valve. Pull the drawer assembly over a pan.","Read the nozzle stamp. GPH and spray must match the unit card. Wrong stamp goes back in the tin.","Set electrode gap and position with the gauge — not your eye. Instructor initials.","Install nozzle and strainer. Restore. Bleed/prime per pump type. Pressure at the pump port vs spec (often 100 psi — use the card).","Fire once. Watch trial for ignition. If it fails, lock out. Do not reset. Find fuel, spark, or cad cell.","On a clean run: cad-cell ohms (typically low, e.g. under the control’s spec — write the number from the door card).","Smoke spot and/or analyzer. Air band only with the instructor.","Planted fault from the instructor. Name the system (fuel, spark, sensing) before you name a part. Write the ticket."],"dataColumns":["Item","Spec","As-found","As-left","Initials"],"dataRows":6,"analysis":[{"id":"a1","type":"calc","prompt":"0.85 GPH nozzle, 140,000 BTU/gal. Input BTU/h at 100 psi nominal?","answer":"119,000 BTU/h","points":3,"work":"0.85 × 140,000 = 119,000"},{"id":"a2","type":"short","prompt":"Why is a second and third reset dangerous after a failed trial?","answer":"Unburned oil pools in the chamber and can puff-back when spark finally catches.","points":4}],"competencies":[{"id":"c1","label":"Electrode geometry to card"},{"id":"c2","label":"Correct nozzle + one clean fire"},{"id":"c3","label":"Cad-cell ohms recorded"},{"id":"c4","label":"No-heat ticket without extra resets"}]},{"source":"filler","id":"lab-shop-hydronic","courseCode":"HCR114","title":"Hydronic loop — fill, tank, purge, ΔT, then the pump","durationMin":90,"groupSize":"Pairs","why":"They will price a circulator while the loop is air-bound. Cold fill, tank air side, purge, ΔT, then prove the pump. That order is the lab.","timebox":"Cold numbers 15. Purge 30. ΔT 20. Prove pump 15. 90-minute bay.","openScript":"Last zone hot before anyone prices a pump. I will feel that last radiator. Cold fill and tank air side get written first. We do not jump the LWCO.","setup":["Trainer cold if you can. Post the shop fill number (often ~12 PSI on a two-story). Relief is 30 PSI — show them where it dumps.","Tire gauge for the tank air side. Isolation valves labeled. One zone you want them to prove.","Optional fault after purge: closed isolation, or a zone valve unplugged — not a dead boiler.","Do not leave yesterday’s jumper on the LWCO."],"instructorRun":["You do not fire a dry boiler. Check water first, every pair.","Stand at purge. They will quit when the first rad is hot. Make them stay until the last one is quiet.","No pump swap until purge + ΔT are on paper.","If relief weeps, they check the tank before they touch the relief."],"holds":[{"step":2,"lookFor":"Cold fill and tank air side written. They should match."},{"step":5,"lookFor":"Last zone hot and quiet. You felt it."},{"step":7,"lookFor":"Circulator proved with heat, hum, and amps — or air/valve named."}],"plantFaults":["Isolation valve closed on the prove zone.","Zone valve unplugged.","Tank air side at 0 PSI (waterlogged demo) if you have a spare tank."],"failLooksLike":["Requesting a pump with a cold last rad and no purge notes.","Jumping LWCO.","Replacing a weeping relief with a waterlogged tank."],"passLine":"Cold fill recorded, tank air matches fill, last zone hot, boiler and zone ΔT on paper, pump proved or air/valve named. No part until then.","objectives":["Read cold fill and match expansion-tank air charge","Purge until the last radiation is hot and quiet","Measure ΔT at the boiler and on one zone","Prove a circulator before anyone prices a pump"],"safety":["Hot water burns. Gloves on the boiler.","Do not fire a dry boiler.","Do not jump the LWCO.","Relief path clear. Know where 30 PSI goes."],"ppe":["Safety glasses","Gloves","Closed-toe boots"],"tools":["Boiler gauge","Tire gauge or tank checker","Clamp meter","Two pipe thermometers","Purge hose"],"materials":["Hydronic trainer","Data sheet"],"procedure":["Cold system. Read fill pressure. Shop target is posted (often ~12 PSI). Write it.","Check expansion-tank air side. It should match cold fill. Record both. Hold for instructor if they disagree by more than 2 PSI.","Open the zone you will prove. Confirm isolation valves are actually open — hands on the handles.","Call for heat. Purge. Stay on the last unit until it is hot and the noise is gone. Do not stop at the first radiator.","Supply and return at the boiler. ΔT. Typical design ~20°F — write actual, not the textbook.","Supply and return on the prove zone. ΔT. If boiler is hot and zone is cold, you have air, a closed valve, or no flow.","Prove the circulator: hot on one port, hum, amp draw vs nameplate. If the zone is still cold, name air or valve before you name the pump. That is the proving step.","Instructor sign-off on purge + numbers. Then, if assigned, take the planted fault."],"dataColumns":["Reading","Target","Measured","Pass?"],"dataRows":6,"analysis":[{"id":"a1","type":"short","prompt":"Boiler 180°F, last rad cold, circulator humming. What did you miss?","answer":"Air bound, zone valve closed, isolation shut, or bypass flow. Not a new boiler. Purge and prove the zone.","points":5},{"id":"a2","type":"short","prompt":"Relief weeps at 30 PSI after heat-up. Tank air side was 0 PSI cold. What failed?","answer":"Waterlogged diaphragm tank. Recharge or replace the tank. Do not just replace the relief.","points":4}],"competencies":[{"id":"c1","label":"Cold fill recorded"},{"id":"c2","label":"Tank air matches fill"},{"id":"c3","label":"Last zone hot and quiet"},{"id":"c4","label":"Boiler and zone ΔT"},{"id":"c5","label":"Circulator proved, not guessed"}]},{"source":"filler","id":"lab-shop-evac","courseCode":"HCR105","title":"Recover, 500-micron pull, decay, weigh-in, SH or SC","durationMin":90,"groupSize":"Pairs","why":"They will charge by gauges and skip the decay test. Legal recovery, 500 microns, decay, weigh-in, then SH/SC. Airflow still comes before a pound of extra refrigerant.","timebox":"Nameplate 10. Recover 20. Evacuate + decay 25. Weigh-in 15. SH/SC 15. 90-minute bay.","openScript":"Micron gauge on the system, not the pump. I start the decay clock. Charge is weighed. No ‘until the gauges look like class.’ Airflow still comes before a second pound.","setup":["Recovery cylinder on a scale, labeled, room to spare under 80% fill. You know the tare.","Micron gauge at the system, not on the pump. Core tools. Fresh drier per trainer.","Decay pass posted: e.g. pull 500, isolate, 5 min, stay under 1000. You pick the number and write it on the board.","Do not leave yesterday’s mixed-refrigerant hoses on the manifold."],"instructorRun":["Photograph nameplates with them. Factory charge and line-set add are law.","You watch recovery into the cylinder. No ‘we vented the trace.’","Decay: you start the clock. They do not bounce the micron gauge to make it pretty.","Weigh-in is weighed. Not ‘until the gauges look like class.’","If SH is high, they check restriction and airflow before they add another half pound."],"holds":[{"step":1,"lookFor":"Nameplate photo. Charge and refrigerant ID written."},{"step":5,"lookFor":"You started the 5-minute decay. Number on the board."},{"step":7,"lookFor":"Scale reading matches nameplate ± shop tolerance."}],"plantFaults":["Loose core after evacuate — decay fails fast. They should nitrogen-stand vs moisture.","Wrong drier orientation if you want to be mean on a later run."],"failLooksLike":["Micron gauge on the pump, system isolated, they call 500 microns.","Charging until suction ‘looks like 70.’","Venting the last trace to ‘save time.’ Lab is over for that pair."],"passLine":"Recovered and logged, 500 microns at the system, decay pass, weighed charge, SH or SC with indoor WB / outdoor DB written.","objectives":["Recover into a legal cylinder and log lbs","Evacuate to 500 microns at the system","Pass a 5-minute decay","Weigh in and verify SH (piston) or SC (TXV)"],"safety":["No venting. EPA 608 applies in this bay.","Cylinders upright, labeled, under 80% fill.","Glasses and gloves around liquid.","Recovery exhaust / ventilation on."],"ppe":["Glasses","Gloves","Closed-toe boots"],"tools":["Recovery machine","DOT cylinder + scale","Vacuum pump","Micron gauge","Manifold","Core tools"],"materials":["Trainer with known charge","New liquid-line drier","Shop refrigerant for weigh-in"],"procedure":["ID refrigerant. Photograph nameplate. Write factory charge and any line-set add. Hold.","Recover to the required vacuum for the category. Log lbs recovered vs what you expected.","Change the drier if the circuit was open. Nitrogen pressure-test if you broke joints.","Micron gauge on the system. Pull to 500 microns. Pump isolated.","Decay 5 minutes. Instructor starts the clock. Pass is the number on the board (example: stay under 1000 microns). Fast rise to atmosphere = leak. Rise that levels = moisture. Prove which.","If wet: nitrogen break and pull again (triple-evac).","Weigh in nameplate plus line-set add. Write the scale. That is the proving step for charge amount.","Run it. Piston: SH vs chart with indoor WB / outdoor DB. TXV: SC vs target, SH not zero. Do not add more until airflow is on the sheet.","Refrigerant movement record as if it were a field job. Names, lbs, cylinder ID."],"dataColumns":["Step","Reading","Spec","Pass?"],"dataRows":8,"analysis":[{"id":"a1","type":"short","prompt":"Microns go 400 → 2500 in one minute after isolate. Leak or moisture? How do you tell?","answer":"Fast climb toward atmosphere is a leak. Moisture rises then levels. Nitrogen standing pressure test vs another pull.","points":4},{"id":"a2","type":"calc","prompt":"R-410A suction 120 psig (sat ≈ 41°F), suction line 53°F. SH? If target is 10°F at 95°F outdoor on a piston, high or low?","answer":"SH = 12°F. Slightly high vs 10°F — slight undercharge or airflow/load. Don’t dump a pound.","points":4,"work":"53 − 41 = 12°F SH"}],"competencies":[{"id":"c1","label":"Legal recovery + log"},{"id":"c2","label":"500 microns at the system"},{"id":"c3","label":"Decay pass"},{"id":"c4","label":"Weigh-in"},{"id":"c5","label":"SH or SC with conditions"}]},{"source":"filler","id":"lab-shop-charge","courseCode":"HCR117","title":"Split charge by SH/SC, then heat-pump modes","durationMin":90,"groupSize":"Pairs","why":"They charge pistons by subcooling and TXVs by ‘gauges look good.’ Airflow first. Chart second. Weighed ounces. Then reversing valve and defrost so they stop calling frost a failed compressor.","timebox":"Airflow 15. One metering device 35 (I pick piston or TXV). Heat-pump modes 20. Ticket 15. 90-minute bay.","openScript":"Gauges stay on the cart until filter, Delta-T, outdoor DB, and indoor WB are on paper. I pick piston or TXV — you do not do both. Ounces on a scale. Frost in heat can be normal — say it out loud.","setup":["Charge charts on the unit, not in a drawer. Pipe-clamp temps that actually read.","Piston trainer and TXV trainer labeled. If one unit, they do piston method then you tell them the metering device.","Heat-pump: you know how to force defrost on that board. Write the button sequence on a card.","Planted faults after a clean charge: dirty filter, weak cap, 6 oz short."],"instructorRun":["No gauges until filter, Delta-T or static, outdoor DB, indoor WB are written.","Ounces on a scale. Not a 3-minute blast from a can.","Stabilize 10 minutes after each add. They will want to chase.","Frost on the outdoor coil in heat can be normal. They must say that out loud before they ‘fix’ it."],"holds":[{"step":1,"lookFor":"Airflow numbers on paper. No gauges yet."},{"step":3,"lookFor":"Target SH from the chart, not memory."},{"step":6,"lookFor":"Defrost: fan stop, reverse, aux if equipped — you saw it."}],"plantFaults":["Dirty filter — high SH, they must catch airflow.","Weak capacitor — compressor or fan down.","Undercharge 6 oz after they already passed — see if they re-check SH vs restriction."],"failLooksLike":["Charging a TXV by superheat only.","Liquid-charging R-410A with the can upside down into a running suction port without you.","Calling outdoor frost in heat a failed compressor."],"passLine":"Airflow proved, piston on target SH, TXV on target SC with SH not zero, heat and defrost demonstrated, one planted no-cool with numbers.","objectives":["Prove airflow before charging","Charge piston by target superheat","Charge TXV by subcooling","Force heat, cool, and defrost on a heat pump"],"safety":["Guards on. Fans rotate.","R-410A hose ratings.","Do not front-seat valves under load unless instructed.","Heat strips are 240 V."],"ppe":["Glasses","Gloves","Hearing protection near condensers"],"tools":["Manifold","Pipe-clamp temps","Psychrometer","Static probes","Charge chart","Scale"],"materials":["Piston split or trainer","TXV trainer","Heat-pump trainer"],"procedure":["Cooling. Filter, TESP or Delta-T, outdoor DB, indoor WB. Write them. Gauges stay on the cart.","Instructor releases gauges. Confirm refrigerant ID.","Piston or TXV — instructor picks one. Piston: target SH from the chart. TXV: target SC, SH not zero. Weighed ounces. Stabilize 10 minutes. That is the proving step for charge.","Heat pump: cool then heat. Suction line goes to the coil that is evaporating. Say which coil is the evaporator in heat (outdoor).","Force defrost per the card. Outdoor fan stops, valve reverses, aux heat if equipped. Time it.","Planted no-cool. Inspect before gauges. Name airflow vs refrigerant vs electrical before a part."],"dataColumns":["Mode","OD DB","ID WB","SH","SC","Delta-T","oz changed"],"dataRows":4,"analysis":[{"id":"a1","type":"short","prompt":"Target SH 8°F. You measure 25°F after +6 oz. What else causes high SH?","answer":"Restriction (drier, piston, kink), low indoor load, sensing error. Check SC and liquid line. Don’t keep pouring.","points":4},{"id":"a2","type":"short","prompt":"Heat mode, outdoor suction frosting heavily. Interpret before you change a compressor.","answer":"Outdoor coil is the evaporator in heat. Frost can be normal. Heavy ice and long run = defrost not working or outdoor airflow blocked.","points":3}],"competencies":[{"id":"c1","label":"Airflow proved before charge"},{"id":"c2","label":"Piston on target SH"},{"id":"c3","label":"TXV on target SC, SH not zero"},{"id":"c4","label":"Heat-pump defrost demonstrated"}]},{"source":"filler","id":"lab-shop-duct","courseCode":"HCR108","title":"Duct — size one run, one joint, seal, one traverse","durationMin":90,"groupSize":"Teams of 3","why":"They cut metal before they size it. Ninety minutes: chart, one joint, seal, one traverse. Not a three-hour catalog duct day.","timebox":"Size 15. One fitting 35. Seal 15. One traverse 15. 90-minute bay — not a 3-hour catalog project.","openScript":"This is ninety minutes, not a three-hour sheet-metal day. Chart first — I initial size before the shear. One joint, sealed, one real traverse. Pretty Pittsburgh with no CFM is a fail.","setup":["Assign CFM and max friction (example 0.08 in. w.c./100 ft) per team. Different numbers so they cannot copy.","Shear, brake, Pittsburgh: gloves at the machine. You run the first demo joint.","Magnehelic zeroed. Pitot or anemometer that actually works. You know a sane velocity for their size.","Mastic, not cloth duct tape, unless the shop spec says listed tape."],"instructorRun":["No one at the shear until the size is on paper and you initialed the chart pick.","Watch fingers at the Pittsburgh. One demo, then they form.","Pressurize only after hang and seal. You stand there for the first blast.","If CFM is 30% low they do not get to say ‘the blower is weak’ until leakage and fittings are named."],"holds":[{"step":1,"lookFor":"Size from the friction chart, math shown. You initial."},{"step":4,"lookFor":"Hanging, sealed, ready to pressurize."},{"step":5,"lookFor":"Traverse written. CFM vs design on the packet."}],"plantFaults":["Leave one uncleared drive cleat on a team’s run — they should find the leak."],"failLooksLike":["Starting at the shear with no chart.","Cloth tape on a shop that specified mastic.","One-hole ‘traverse.’"],"passLine":"Chart size initialed, run fabricated and sealed, traverse CFM within shop tolerance or the miss explained with leakage/fittings, not vibes.","objectives":["Size a short run from a friction chart","Fabricate and seal to shop spec","Traverse and compare CFM to design"],"safety":["Cut gloves at brake and shear.","Hearing and eye protection on power tools.","No loose clothing at the Pittsburgh.","File and hem sharp edges."],"ppe":["Glasses","Cut gloves","Hearing protection","Boots"],"tools":["Tape, marker, snips","Pittsburgh / snap-lock","Drill","Magnehelic + pitot or anemometer","Friction chart"],"materials":["Sheet metal","Drive / S-slips","Mastic or listed tape","Hanging strap"],"procedure":["Assigned CFM and friction rate. Pick size from the chart. Show the math. Instructor initials before you cut.","One fitting only — a joint or a short straight with one seam. Hem edges. This is not a whole-house run.","Seal to shop spec now. No ‘we’ll mastic it later.’","Set it on the test rig or hang the short piece. Instructor walk-around.","Static plus a real traverse (more than one hole). CFM = FPM × area vs design. That is the proving step.","Name leakage if CFM is short. Three notes. You’re done — 90 minutes."],"dataColumns":["Station","Velocity FPM","Area ft²","CFM","Static in. w.c."],"dataRows":6,"analysis":[{"id":"a1","type":"calc","prompt":"400 FPM through 0.50 ft². CFM?","answer":"200 CFM","points":3,"work":"400 × 0.5 = 200"},{"id":"a2","type":"short","prompt":"Measured CFM is 30% low. Three causes. Not ‘blower bad’ as the first line.","answer":"Leakage, extra fittings, crushed flex, wrong blower tap, dirty coil/filter on the rig, bad traverse.","points":3}],"competencies":[{"id":"c1","label":"Chart size initialed"},{"id":"c2","label":"Fabrication quality"},{"id":"c3","label":"Sealed joints"},{"id":"c4","label":"Traverse CFM vs design"}]},{"source":"filler","id":"lab-shop-box","courseCode":"HCR109","title":"Walk-in / reach-in — box TD, defrost, pump-down","durationMin":90,"groupSize":"Pairs","why":"They add charge because the box is warm. TD vs design, defrost that actually clears, pump-down with LOTO. Ice after defrost is a defrost problem until proven otherwise.","timebox":"TD 20. Defrost 25. Pump-down 20. Ticket 15. 90-minute bay.","openScript":"Door pinned — I see it before you go in. High TD is not ‘add gas.’ Ice after defrost is a defrost problem. LOTO after pump-down; it will restart.","setup":["Pin or wedge walk-in doors. Nobody latches a student in.","Post design TD for that coil (example 10°F). Timer access labeled.","You know how to force defrost on this box. Heaters are 208/240 — say it in the open.","Pump-down: solenoid or king valve — label which this trainer uses."],"instructorRun":["Door pinned. You check before they go in.","They record box temp and SST before they touch a charge cylinder.","Watch heater amps in defrost. A ‘completed’ defrost with ice left is a fail.","Pump-down: LOTO after the pump-down. Automatic restart will bite them."],"holds":[{"step":1,"lookFor":"Door pinned. You saw it."},{"step":3,"lookFor":"TD vs design on paper. No charge added yet."},{"step":6,"lookFor":"Pump-down standing suction + LOTO before they open anything."}],"plantFaults":["Defrost heater lead off — ice remains.","Fan running in defrost if you can jumper that trainer."],"failLooksLike":["Adding gas because TD is high.","Unlatched walk-in with a student inside.","Opening the circuit after pump-down without LOTO."],"passLine":"TD recorded vs design, defrost timed with heater amps and a clear coil, pump-down + LOTO, PM checklist complete.","objectives":["Measure box TD and SST","Force and verify a defrost","Pump down and LOTO","Complete a commercial PM checklist"],"safety":["Pin the walk-in door. Never latch a student in.","Defrost heaters are 208/240 V.","LOTO after pump-down — it will restart.","Recovery rules if you open the circuit."],"ppe":["Glasses","Gloves","Warm layer in a freezer"],"tools":["Manifold","Clamp temps","Clamp meter","Stopwatch","Ticket pad"],"materials":["Walk-in or reach-in trainer","Defrost timer access"],"procedure":["Pin the door. Instructor sees the pin.","Setpoint, actual box, suction, head, line temps, SH, SC, SST, box TD.","TD vs the posted coil rating. High TD = dirty/iced/starved/undersized — not ‘add gas’ first. Hold.","Force defrost. Record termination method, heater amps, time to a clear coil. Ice still there = fail that defrost.","Freezer: drain heat. Fan delay if equipped. Write yes/no, not ‘seemed fine.’","Pump down with the solenoid or king valve as labeled. Standing suction. LOTO. Proving step = it does not restart in your face.","Restart. Oil, sight glass, box pulling down. PM checklist as a field tech would leave it."],"dataColumns":["Reading","As-found","Spec / notes"],"dataRows":8,"analysis":[{"id":"a1","type":"calc","prompt":"Box 36°F, SST 22°F. TD? Design is 10°F. Is the coil happy?","answer":"TD = 14°F. Higher than 10 — dirty, iced, starved, or undersized. Don’t just add charge.","points":4},{"id":"a2","type":"short","prompt":"Ice still on the coil after a ‘completed’ defrost. Causes?","answer":"Heater open, short defrost, failed termination, fan in defrost, frozen drain, door infiltration.","points":3}],"competencies":[{"id":"c1","label":"TD vs design, no extra charge first"},{"id":"c2","label":"Defrost cleared the coil"},{"id":"c3","label":"Pump-down + LOTO"},{"id":"c4","label":"PM checklist"}]},{"source":"filler","id":"lab-shop-fault","courseCode":"HCR110","title":"Planted-fault RTU — inspect, measure, isolate, ticket","durationMin":90,"groupSize":"Pairs (lead + helper)","why":"This is the job. Complaint in, numbers out, one system named, then one part. They will want gauges first. You will not hand gauges until inspect is done.","timebox":"Complaint 5. Inspect 15. Measure 20. Isolate 10. Prove 20. Ticket 15. One fault — no swap. 90-minute bay.","openScript":"I am dispatch. One-line complaint. Three questions, then I’m quiet. Gauges stay on my cart until inspect is on paper. Name the system before you name a part. One fault. Ninety minutes.","setup":["One fault per unit, written on a card in your pocket. Capacitor, filter, contactor, fan motor, thermostat wire — not three at once.","Ticket form is the shop form, not a blank page.","Lead owns the meter and the disconnect. Helper does not work live without eye contact.","Three-phase mockup: tape the wild leg. No random jumpering."],"instructorRun":["You are dispatch. One-line complaint. They may ask three questions. Then you are quiet.","Gauges stay on your cart until they have filter, belts, disconnect, codes, condenser, drain on paper.","They must name the failed system (air / refrigerant / electrical / controls) before a part.","Wrong part request costs a grade step. Prove the fix with after numbers.","Swap lead/helper on the second fault if time."],"holds":[{"step":2,"lookFor":"Inspect list complete. Gauges still on the cart."},{"step":4,"lookFor":"System named out loud. Then they may request a part."},{"step":6,"lookFor":"After numbers on the ticket. You initial proof."}],"plantFaults":["Open run capacitor.","Dirty filter / blocked return.","Contactor welded or coil open.","Condenser fan unplugged.","Y not making at the board."],"failLooksLike":["Gauges on before a filter check.","Helper live without the lead watching.","Ticket: ‘unit bad, added gas.’"],"passLine":"Inspect before gauges, correct system isolated, one justified part, after numbers on a ticket a service manager would accept.","objectives":["Four-step path under time: complaint → inspect → measure → prove","Isolate airflow vs refrigerant vs electrical","Write a service-manager ticket"],"safety":["RTU is a field unit. LOTO before guards off.","Lead owns the meter and disconnect.","Helper does not work live without eye contact.","No random jumpering on three-phase."],"ppe":["Glasses","Gloves","Hard hat if posted"],"tools":["Full service bag","Manifold (released later)","Meter","Static probes","Ticket form"],"materials":["RTU or packaged trainer","Instructor fault"],"procedure":["Dispatch (instructor) gives a one-line complaint. Ask up to three questions. Write the complaint on the ticket.","Inspect: filters, belts, disconnect, board codes, condenser, drain, obvious damage. Gauges stay on the cart. Hold.","Measure: voltage all legs, amps, temps, static. Then ask for gauges if the numbers justify refrigerant.","Name the failed system out loud (airflow / refrigerant / controls / power). Then name one part. Hold.","Repair or request the part. One request. Extra guesses cost points.","Prove the fix. After numbers on the ticket. Instructor initials proof. Bay is done — no second fault today."],"dataColumns":["Check","Before","After"],"dataRows":8,"analysis":[{"id":"a1","type":"short","prompt":"Condenser fan motor failed. What numbers prove it, and what else do you inspect?","answer":"Voltage present, winding open/grounded or locked rotor, capacitor µF. Also blade clearance and whether high head cooked the compressor.","points":4},{"id":"a2","type":"short","prompt":"Rewrite: ‘Unit bad. Added gas. All good.’","answer":"Model/serial, complaint, filter/static, SH/SC before-after, lbs, leak-test result, run verification, name.","points":4}],"competencies":[{"id":"c1","label":"Inspect before gauges"},{"id":"c2","label":"Correct system isolated"},{"id":"c3","label":"Fix proved with numbers"},{"id":"c4","label":"Ticket a manager would take"},{"id":"c5","label":"Lead / helper discipline"}]},{"source":"filler","id":"lab-shop-capstone","courseCode":"HCR200","title":"Capstone call — mixed equipment, one part, proof photos","durationMin":90,"groupSize":"Lead tech + helper","why":"Last gate. They run a bay like a field lead: brief, diagnose, one part, prove, debrief. Extra guesses cost points. Safety brief is graded.","timebox":"Brief 10. Inspect/measure 15 locked. Repair 40. Proof + debrief 20. 90-minute bay.","openScript":"Safety brief or the toolbox stays shut. Fifteen minutes before you ask for a part. One part. Say the number that justifies it. This is not a three-hour scavenger hunt.","setup":["Randomize bays: furnace, split, heat pump, hydronic, walk-in. Card in an envelope.","Safety brief sheet they sign. Inverter wait-time posted on mini-splits. CO rules on heat.","You are dispatch and parts counter. They get one part or one return-trip item.","Phone camera for proof shots of meters and gauges. No faces required."],"instructorRun":["You initial the safety brief or they do not open the toolbox.","15 minutes inspect/measure before any part request. Timer visible.","Parts counter: ‘why this part?’ If they cannot say the number, no part.","Debrief is required. The other team hears the measurement that saved a wrong part."],"holds":[{"step":1,"lookFor":"Safety brief signed. You initialed."},{"step":3,"lookFor":"15-minute timer done. Part request justified with a number."},{"step":5,"lookFor":"Proof photos and ticket complete."}],"plantFaults":["Match the bay: flame rod, weak cap, air-bound zone, iced evaporator, failed defrost, open limit — one only."],"failLooksLike":["Toolbox open before the brief.","Two part guesses.","No after numbers."],"passLine":"Brief signed, disciplined diagnosis, one justified part, proof photos, ticket, debrief. Field-lead behavior, not a scavenger hunt.","objectives":["Run dispatch-to-proof on mixed equipment","Combine electrical and refrigeration or combustion numbers","Brief the bay like a field lead"],"safety":["Capstone brief signed before tools.","Inverter wait-time on mini-splits.","CO rules on heating.","Recovery log if the circuit opens."],"ppe":["Full shop PPE","Task extras as briefed"],"tools":["Rolling cart","OEM card / QR if available","Ticket + EPA log"],"materials":["Assigned bay"],"procedure":["Lead briefs: hazards, LOTO owner, goal, helper tasks. Instructor initials. Hold.","Open the envelope. Complaint is realistic. Timer starts.","15 minutes inspect and measure. Then one part request at the counter, with the number that justifies it. Hold.","Repair. Prove. Photograph meter and gauge readings for the portfolio.","Ticket complete. EPA log if you moved refrigerant.","Debrief the other team: the measurement that saved a wrong part."],"dataColumns":["Time","Action","Measurement","Decision"],"dataRows":8,"analysis":[{"id":"a1","type":"short","prompt":"Warranty compressor claim. Which measurements must be on this ticket?","answer":"Ohms to ground, amps vs RLA, SH/SC, drier ΔT, voltage, oil/acid if the OEM asks, model/serial, runtime story.","points":5}],"competencies":[{"id":"c1","label":"Safety brief signed"},{"id":"c2","label":"15-minute disciplined diagnosis"},{"id":"c3","label":"One-part request justified"},{"id":"c4","label":"Proof photos / numbers"},{"id":"c5","label":"Lead debrief"}]}];
window.LINCOLN_CATALOG_LABS = [{"source":"lincoln","id":"lab-hcr101-tubing","courseCode":"HCR101","title":"Copper Coupon — Cut, Flare, Swage, Solder, Pressure-Test","durationMin":90,"groupSize":"Pairs","objectives":["Produce square, reamed cuts on 3/8 in. and 1/4 in. ACR copper","Build a 45° flare that seats without splitting","Swage and soft-solder a coupling-less joint","Nitrogen-test the assembly and find any leak"],"safety":["Eye protection on at all times in the bay","Torch only on the fire brick; know the extinguisher location","Nitrogen regulator set by the instructor — never use oxygen","Hot copper looks like cold copper; quench and rack coupons"],"ppe":["Safety glasses","Gloves for hot work","Closed-toe boots","Shop shirt (no synthetics at the torch)"],"tools":["Tubing cutter","Reamer","Flaring yoke","Swage punch / expander","Torch and solder","Nitrogen regulator and whip","Bubble solution","Flare-nut wrenches"],"materials":["3/8 in. and 1/4 in. ACR copper","Flare nuts","Solder and flux","Sand cloth","Name tag"],"procedure":["Draw the coupon sketch: 8 in. of 3/8 in. with a 45° flare on one end, a swaged joint to 1/4 in., and a capped or flared test fitting on the other.","Cut, ream, and clean. Instructor checks burrs before you flare.","Flare the 3/8 in. end. Inspect for even face, no cracks, correct length past the nut.","Swage the opposite end and insert 1/4 in. tube to proper depth.","Flux, heat, and pull solder. Wipe. No blobs, no unfilled capillary.","Cap and nitrogen-test to the shop pressure (typically 100–150 psig). Soap every joint.","Hold 3 minutes. Any drop = find and repair, then retest.","Stamp your initials. Submit for the joint-quality rubric."],"dataColumns":["Joint","Visual (pass/fail)","Leak (Y/N)","psig start","psig end","Notes"],"dataRows":4,"analysis":[{"id":"a1","type":"short","prompt":"If the flare split, what did you do wrong and how do you prevent it?","answer":"Over-flaring, dull cone, unreamed tube, or work-hardened copper. Cut back, ream, anneal if needed, don’t over-travel the yoke.","points":4},{"id":"a2","type":"short","prompt":"Why is a soap test on nitrogen not a substitute for an electronic search once refrigerant is in a system?","answer":"Soap finds wet joints at high ΔP; tiny refrigerant leaks in air need electronic/ultrasonic methods. Nitrogen soap is for fabrication QA.","points":3}],"competencies":[{"id":"c1","label":"Square cut and ream"},{"id":"c2","label":"Serviceable 45° flare"},{"id":"c3","label":"Filled solder joint"},{"id":"c4","label":"Nitrogen test with no leak"}]},{"source":"lincoln","id":"lab-hcr102-circuits","courseCode":"HCR102","title":"Series/Parallel Board and Motor ID","durationMin":90,"groupSize":"Pairs","objectives":["Build and measure a series and a parallel circuit","Prove Ohm’s law with a meter","Identify C, S, R on a compressor and check a capacitor"],"safety":["Boards are low-voltage unless the instructor energizes 120 V trainers","One hand in pocket on live 120/240 V; CAT-rated meter","Discharge capacitors with a resistor before handling","LOTO any motor that will be ohm’ed at the terminals"],"ppe":["Safety glasses","Meter with insulated probes","No jewelry on live panels"],"tools":["DMM","Clamp-on (if 120 V)","Capacitor tester","Screwdrivers","Alligator leads"],"materials":["Trainer board","Known resistors/lamps","Dual run capacitor","Isolated compressor or motor"],"procedure":["Build a series circuit of two known loads. Predict current and voltage drops. Energize and measure.","Rebuild as parallel. Predict branch currents and total. Measure.","Record percent error. Errors > 10% mean you re-measure or check meter category/range.","On the isolated compressor: measure C-S, C-R, S-R. Identify terminals. Measure winding to ground (should be OL).","Discharge and test the dual capacitor (µF vs. nameplate ±6%).","Instructor inserts an open or short on the board. Diagnose with the meter only — no peeking under the tape."],"dataColumns":["Circuit","Predicted I","Measured I","Predicted V drop","Measured V","% error"],"dataRows":4,"analysis":[{"id":"a1","type":"calc","prompt":"Series: two 50 Ω resistors on 24 V. Predicted I and each voltage drop?","answer":"I = 0.24 A; 12 V each","points":4,"work":"Rt=100 Ω; I=24/100=0.24 A; VR=0.24×50=12 V"},{"id":"a2","type":"short","prompt":"Your C-S reading is OL but C-R and R-S are normal-ish. What failed?","answer":"Start winding open (or overload in that path). Compressor will not start.","points":3}],"competencies":[{"id":"c1","label":"Correct series measurements"},{"id":"c2","label":"Correct parallel measurements"},{"id":"c3","label":"Compressor terminal ID"},{"id":"c4","label":"Capacitor µF test"},{"id":"c5","label":"Diagnose planted open/short"}]},{"source":"lincoln","id":"lab-hcr103-furnace","courseCode":"HCR103","title":"Gas Furnace Sequence and Combustion","durationMin":90,"groupSize":"Pairs","objectives":["Meter a complete call-for-heat sequence","Measure manifold pressure and flame-sensor microamps","Perform a combustion analysis and record CO"],"safety":["CO monitor on in the bay; know shutdown if ambient CO rises","Do not jumper rollout or limit for convenience","Combustion air and venting confirmed before firing","Instructor present for any live gas-train work"],"ppe":["Glasses","Gloves","Hearing protection if required","CO personal monitor if issued"],"tools":["DMM with µA","Manometer (in. w.c.)","Combustion analyzer","Static probes","Schematic"],"materials":["Running gas furnace trainer","Analyzer paper filters","Cleaning kit for flame sensor"],"procedure":["Walk the furnace: model, gas type, venting, filter, and schematic highlighter path for W.","Call for heat. Time each step: inducer, pressure switch, igniter, valve, flame, blower.","Measure manifold pressure; compare to nameplate (NG ~ 3.5 in. w.c.). Do not adjust without instructor.","Series-measure flame-sensor microamps. Clean the rod if low; re-measure.","Analyzer in the flue per probe depth. Record O2, CO, CO2, stack, efficiency, and ambient CO.","Measure TESP and temperature rise; compare to nameplate rise range.","Instructor plants a fault (hose off, dirty sensor, unplugged inducer). Diagnose and write a ticket."],"dataColumns":["Step","Expected","Measured","Spec","Pass?"],"dataRows":8,"analysis":[{"id":"a1","type":"short","prompt":"Temperature rise is above the nameplate range. What are the first three airflow checks?","answer":"Filter, blower speed/ECM taps, supply/return static and closed registers. Do not open the gas valve to “help.”","points":4},{"id":"a2","type":"short","prompt":"Ambient CO is 35 ppm and rising with the furnace firing. Your actions?","answer":"Shut the unit down, ventilate, keep people out, notify instructor — do not keep firing to finish the lab.","points":4}],"competencies":[{"id":"c1","label":"Sequence timed and metered"},{"id":"c2","label":"Manifold pressure recorded"},{"id":"c3","label":"Flame-sensor µA in spec"},{"id":"c4","label":"Combustion numbers recorded safely"},{"id":"c5","label":"Planted-fault ticket"}]},{"source":"lincoln","id":"lab-hcr114-oil","courseCode":"HCR114","title":"Oil Burner Setup, Fire, and Hydronic Purge","durationMin":90,"groupSize":"Pairs","objectives":["Set electrodes and verify nozzle/pump pressure","Fire a burner and read smoke/CO2","Purge a hydronic zone and set fill pressure"],"safety":["Fuel-oil spills contained immediately; no torches near mist","Reset primary controls only as instructed — no repeated reset into a wet firebox","Hot breech and boiler sections — gloves","Know the oil shutoff and electrical LOTO"],"ppe":["Glasses","Nitrile/oil gloves","Shop coat","Hearing protection as posted"],"tools":["Nozzle wrench","Electrode gauge","Pressure gauge on pump port","Smoke tester / analyzer","Multimeter (cad cell)"],"materials":["Correct GPH nozzle","Electrodes","Oil filter element","Rags and drip pan"],"procedure":["Shut down and LOTO. Remove drawer assembly. Inspect nozzle, strainer, and electrodes.","Set electrode gap and position to manufacturer card. Photograph or have instructor initial.","Install a known-good nozzle. Restore. Prime/bleed per pump type.","Fire. Observe trial for ignition. Cad-cell ohms in run (typically low, e.g. < 1600 Ω — use the control’s spec).","Smoke spot and/or analyzer. Adjust air band only with instructor coaching.","On the hydronic trainer: note cold-fill, expansion-tank precharge (isolated), purge zones until quiet, record supply/return temps.","Write a no-heat oil ticket from a planted fault (cad cell covered, closed valve, tripped primary)."],"dataColumns":["Item","Spec","As-found","As-left","Initials"],"dataRows":6,"analysis":[{"id":"a1","type":"calc","prompt":"0.85 GPH nozzle, 140,000 BTU/gal. Input BTU/h at 100 psi (nominal)?","answer":"119,000 BTU/h","points":3,"work":"0.85 × 140,000 = 119,000"},{"id":"a2","type":"short","prompt":"Why is repeated reset on a failed cad-cell trial dangerous?","answer":"Unburned oil pools in the chamber and can puff-back on the next successful spark.","points":4}],"competencies":[{"id":"c1","label":"Electrode geometry"},{"id":"c2","label":"Clean fire / smoke"},{"id":"c3","label":"Cad-cell diagnosis"},{"id":"c4","label":"Hydronic purge and fill"}]},{"source":"lincoln","id":"lab-hcr105-evac","courseCode":"HCR105","title":"Recover, Triple-Evacuate, Weigh-In, Superheat/Subcooling","durationMin":90,"groupSize":"Pairs","objectives":["Recover into a legal cylinder and log the amount","Evacuate to 500 microns and pass a decay test","Weigh in and verify SH or SC for the metering device"],"safety":["EPA 608 rules apply — no venting","Cylinders upright, labeled, not overfilled","Gloves and glasses around liquid refrigerant","Recovery machine exhaust / ventilation on"],"ppe":["Glasses","Gloves","Closed-toe boots"],"tools":["Recovery machine","DOT recovery cylinder + scale","Vacuum pump","Micron gauge","Manifold","Core tools"],"materials":["Trainer with known charge","New liquid-line drier","Shop refrigerant for weigh-in"],"procedure":["Identify refrigerant, record factory charge and any line-set add. Photograph the nameplate.","Recover to the required vacuum for the category. Log lbs recovered. Close valves; compare to expected.","Replace the drier. Pressure-test with nitrogen if joints were opened.","Evacuate: pull to 500 microns. Valve off the pump. Decay 5 minutes — instructor sets the pass threshold (e.g., stay under 1000 microns).","If wet, triple-evac with dry nitrogen breaks.","Weigh in the nameplate charge (plus line-set add if any).","Run the system. Measure SH (piston) or SC (TXV). Record indoor WB / outdoor DB.","Complete the refrigerant movement record as if it were a field job."],"dataColumns":["Step","Reading","Spec","Pass?"],"dataRows":8,"analysis":[{"id":"a1","type":"short","prompt":"Microns rise from 400 to 2500 in one minute after isolating the pump. Leak or moisture? How do you tell?","answer":"Fast rise to atmospheric suggests leak. Rise that slows and levels (e.g., 1500–2000) often remaining moisture. Nitrogen standing test vs. another pull tells you.","points":4},{"id":"a2","type":"calc","prompt":"R-410A suction 120 psig (sat ≈ 41°F), suction line 53°F. Superheat? Is a piston system at 95°F outdoor likely under or over if target SH is 10°F?","answer":"SH = 12°F; slightly high vs 10°F — slightly undercharged or mild airflow/load effect. Don’t dump a pound; weigh the decision.","points":4}],"competencies":[{"id":"c1","label":"Legal recovery + log"},{"id":"c2","label":"500-micron pull + decay"},{"id":"c3","label":"Weigh-in"},{"id":"c4","label":"SH/SC recorded correctly"}]},{"source":"lincoln","id":"lab-hcr117-charge","courseCode":"HCR117","title":"Split-System Charge and Heat-Pump Mode Check","durationMin":90,"groupSize":"Pairs","objectives":["Prove airflow before charging","Charge a piston system by target superheat and a TXV by subcooling","Force heat, cool, and defrost on a heat-pump trainer"],"safety":["Rotating fans — guards on","High-side hoses rated for R-410A","Do not front-seat service valves under load without instruction","Aux heat strips — treat as live 240 V"],"ppe":["Glasses","Gloves","Hearing protection near condensers"],"tools":["Manifold","Pipe-clamp temps","Psychrometer / WB","Anemometer or static probes","Manufacturer charge chart"],"materials":["Piston split or trainer","TXV trainer or same unit with TXV","Heat-pump trainer"],"procedure":["Cooling: measure filter, TESP, return/supply DB (Delta-T), and outdoor DB / indoor WB.","Piston unit: find target superheat on the chart. Adjust charge in small weighed amounts. Stabilize 10+ minutes.","TXV unit: charge to target subcooling. Confirm SH is not zero (floodback).","Heat pump: verify reversing valve in cool and heat (suction line should go to the active evaporator).","Initiate defrost (procedure per trainer). Confirm outdoor fan stop, reversing, and aux heat if equipped.","Write a no-cool ticket from a planted fault (bad cap, dirty filter, undercharge)."],"dataColumns":["Mode","OD DB","ID WB","SH","SC","Delta-T","Amps"],"dataRows":4,"analysis":[{"id":"a1","type":"short","prompt":"Target SH is 8°F; you measure 25°F after adding 6 oz. What else could cause high SH?","answer":"Restriction (drier, piston, kink), low indoor load / high airflow, sensing error, or still not enough charge — check SC and liquid line temp too.","points":4},{"id":"a2","type":"short","prompt":"In heat mode the suction line at the outdoor unit is cold and frosting heavily. Interpret.","answer":"Outdoor coil is the evaporator in heat — frost can be normal in cold weather. Heavy ice with long run times means defrost isn’t working or airflow across the outdoor coil is blocked.","points":3}],"competencies":[{"id":"c1","label":"Airflow proved"},{"id":"c2","label":"Piston charged by SH"},{"id":"c3","label":"TXV charged by SC"},{"id":"c4","label":"Heat-pump modes demonstrated"}]},{"source":"lincoln","id":"lab-hcr108-duct","courseCode":"HCR108","title":"Duct Project — Fabricate, Seal, Test","durationMin":90,"groupSize":"Teams of 3","objectives":["Size a short run from a friction chart","Fabricate and seal to shop standard","Measure static and estimate CFM"],"safety":["Cut-resistant gloves at the brake and shear","Hearing and eye protection when using power tools","No loose clothing at the Pittsburgh machine","Sharp edges — file and hem as specified"],"ppe":["Glasses","Cut gloves","Hearing protection","Boots"],"tools":["Tape, marker, aviation snips","Pittsburgh / snap-lock as equipped","Drill","Magnehelic + pitot or anemometer","Friction chart"],"materials":["Sheet metal","Drive cleats / S-slips","Mastic or approved tape","Hanging strap"],"procedure":["Assigned CFM and maximum friction rate. Pick diameter or rectangular size from the chart. Show math on the packet.","Layout, cut, and form the run including one elbow and a takeoff or boot as assigned.","Seal joints to shop spec. Hang the run so it can be pressurized.","Connect a shop blower or use the classroom air handler. Measure TESP or duct static and a velocity traverse.","Compare measured CFM to design. Note leakage (audible, smoke, or duct-blaster if available).","Team debrief: what you would change in layout or sealing."],"dataColumns":["Station","Velocity FPM","Area ft²","CFM","Static in. w.c."],"dataRows":6,"analysis":[{"id":"a1","type":"calc","prompt":"400 FPM through 0.50 ft². CFM?","answer":"200 CFM","points":3,"work":"CFM = FPM × area = 400 × 0.5 = 200"},{"id":"a2","type":"short","prompt":"Measured CFM is 30% low. Name three causes.","answer":"Leakage, extra fittings/restrictions, blower not on the design speed, crushed flex, dirty coil/filter on the test rig, traverse error.","points":3}],"competencies":[{"id":"c1","label":"Correct size from friction chart"},{"id":"c2","label":"Fabrication quality"},{"id":"c3","label":"Sealed joints"},{"id":"c4","label":"Static/CFM recorded"}]},{"source":"lincoln","id":"lab-hcr109-box","courseCode":"HCR109","title":"Walk-in / Reach-in — TD, Defrost, and Pump-Down","durationMin":90,"groupSize":"Pairs","objectives":["Measure box TD and SST","Time and verify a defrost","Pump down and restart a commercial trainer"],"safety":["Watch automatic restart after pump-down — LOTO before opening the circuit","Defrost heaters are 208/240 V","Walk-in doors: never latch a student inside; pin the door","Refrigerant recovery rules still apply"],"ppe":["Glasses","Gloves","Warm layer if working in a freezer"],"tools":["Manifold","Clamp temps","Ammeter","Stopwatch","Ticket pad"],"materials":["Walk-in or reach-in trainer","Defrost timer access"],"procedure":["Record box setpoint, actual box temp, suction/head, line temps, SH, SC, and evaporator TD.","Compare TD to design (instructor posts the coil rating).","Initiate or wait for defrost. Record termination method, heater amps, and time to clear.","Confirm drain heat (freezer) and that the fan delay works if equipped.","Pump down using the liquid solenoid / king valve as equipped. Record standing suction.","Restart. Watch oil and sight glass. Complete a commercial PM checklist."],"dataColumns":["Reading","Cooler","Spec / notes"],"dataRows":8,"analysis":[{"id":"a1","type":"calc","prompt":"Box 36°F, SST 22°F. TD? If design TD is 10°F, is the coil happy?","answer":"TD = 14°F — higher than 10°F; coil dirty/iced/undersized/starved. Don’t just add charge.","points":4},{"id":"a2","type":"short","prompt":"Ice on the coil after a completed defrost. Causes?","answer":"Heater failed, too short defrost, failed termination, fan running in defrost, drain frozen, door/infiltration overload.","points":3}],"competencies":[{"id":"c1","label":"TD and SST recorded"},{"id":"c2","label":"Defrost verified"},{"id":"c3","label":"Pump-down performed"},{"id":"c4","label":"PM checklist complete"}]},{"source":"lincoln","id":"lab-hcr110-fault","courseCode":"HCR110","title":"Planted-Fault RTU — Isolate and Ticket","durationMin":90,"groupSize":"Pairs (lead + helper)","objectives":["Use the four-step diagnostic path under time","Isolate airflow vs. refrigerant vs. electrical","Write a service-manager-ready ticket"],"safety":["Treat the RTU as a field unit: LOTO before guards off","Three-phase mockups — no random jumpering","Lead tech owns the meter and the disconnect","Helper does not work live without eye contact with lead"],"ppe":["Glasses","Gloves","Hard hat if posted (roof sim)"],"tools":["Full service bag","Manifold","Meter","Static probes","Ticket form"],"materials":["RTU or packaged trainer with instructor fault"],"procedure":["Receive a one-line complaint from dispatch (instructor). You may ask three questions.","Inspect before gauges: filters, belts, disconnect, codes, condenser, drain.","Measure: voltage (all legs), amps, temps, static, then gauges if justified.","State the failed system (airflow / refrigerant / controls / power) before naming a part.","Repair or request the part. Prove the fix with after numbers.","Write the ticket. Swap roles and take a second fault if time."],"dataColumns":["Check","Before","After"],"dataRows":8,"analysis":[{"id":"a1","type":"short","prompt":"You found a failed condenser fan motor. What numbers prove it, and what else must you inspect?","answer":"Voltage present, winding open/grounded or locked rotor amps, capacitor µF. Inspect the capacitor, blade clearance, and whether high head damaged the compressor.","points":4},{"id":"a2","type":"short","prompt":"Rewrite this bad ticket: “Unit bad. Added gas. All good.”","answer":"Should include model/serial, complaint, filter/static, SH/SC before-after, lbs added, why it was low (leak test result), and run verification.","points":4}],"competencies":[{"id":"c1","label":"Inspect before gauges"},{"id":"c2","label":"Correct system isolated"},{"id":"c3","label":"Fix proved with numbers"},{"id":"c4","label":"Ticket complete"},{"id":"c5","label":"Lead/helper discipline"}]},{"source":"lincoln","id":"lab-hcr200-capstone","courseCode":"HCR200","title":"Capstone Service Call — Mixed Equipment","durationMin":90,"groupSize":"Lead tech + helper","objectives":["Run a randomized ticket from dispatch to proof","Combine electrical and refrigeration measurements","Brief the bay like a field lead"],"safety":["Capstone safety brief signed before tools come out","Inverter wait-time if assigned a mini-split","Combustion CO rules if assigned heating","Recovery log if the circuit is opened"],"ppe":["Full shop PPE","Task-specific extras as briefed"],"tools":["Everything in the rolling cart","Manufacturer app/QR if available","Ticket + EPA log"],"materials":["Assigned bay (heating, cooling, or commercial)"],"procedure":["Lead briefs: hazards, LOTO owner, goal, and helper tasks. Instructor initials the brief.","Dispatch issues a realistic complaint. 15-minute inspect/measure before any part request.","Request one part or one “return trip” item. Extra guesses cost points.","Repair and prove. Photograph meter/gauge readings for the portfolio.","Debrief with the other team: what measurement saved you from a wrong part."],"dataColumns":["Time","Action","Measurement","Decision"],"dataRows":8,"analysis":[{"id":"a1","type":"short","prompt":"Attach your ticket. What measurement would you still want if this were a warranty compressor claim?","answer":"Winding ohms to ground, amps vs RLA, SH/SC, liquid line drier ΔT, voltage, and oil/acid as required by the OEM.","points":5}],"competencies":[{"id":"c1","label":"Safety brief"},{"id":"c2","label":"Disciplined diagnosis"},{"id":"c3","label":"One-part request justified"},{"id":"c4","label":"Proof photos / numbers"},{"id":"c5","label":"Lead communication"}]}];
